function deepFreeze(o) {
  for (const v of Object.values(o)) if (v !== null && typeof v === "object") deepFreeze(v);
  return Object.freeze(o);
}
deepFreeze(strings);

function matchBrace(s, i) {
  let depth = 1, j = i + 1;
  while (j < s.length && depth) {
    if (s[j] === "{") depth++;
    else if (s[j] === "}") depth--;
    j++;
  }
  if (depth) throw new Error("unbalanced message: " + s);
  return j;
}

function parseOptions(s) {
  const opts = Object.create(null);
  let i = 0;
  while (i < s.length) {
    while (i < s.length && /\s/.test(s[i])) i++;
    if (i >= s.length) break;
    const m = /^[=\w]+/.exec(s.slice(i));
    if (!m) throw new Error("bad plural options: " + s);
    i += m[0].length;
    while (/\s/.test(s[i])) i++;
    if (s[i] !== "{") throw new Error("bad plural options: " + s);
    const j = matchBrace(s, i);
    opts[m[0]] = s.slice(i + 1, j - 1);
    i = j;
  }
  return opts;
}

function expr(inner, params) {
  const m = /^\s*(\w+)\s*(?:,\s*plural\s*,([\s\S]*))?$/.exec(inner);
  if (!m) throw new Error("bad expression: {" + inner + "}");
  const v = Object.prototype.hasOwnProperty.call(params, m[1]) ? params[m[1]] : undefined;
  if (v === undefined) throw new Error("missing parameter: " + m[1]);
  if (m[2] === undefined) return String(v);
  const opts = parseOptions(m[2]);
  const key = ("=" + v) in opts ? "=" + v : v === 1 ? "one" : "other";
  const branch = opts[key] ?? opts.other;
  if (branch === undefined) throw new Error("missing plural branch: " + key);
  return format(branch, params, String(v));
}

export function format(msg, params = {}, hash) {
  if (params === null) params = {};
  if (typeof params !== "object") throw new Error("params must be an object");
  let out = "";
  let i = 0;
  while (i < msg.length) {
    if (msg[i] !== "{") { out += msg[i] === "#" && hash !== undefined ? hash : msg[i]; i++; continue; }
    const j = matchBrace(msg, i);
    out += expr(msg.slice(i + 1, j - 1), params);
    i = j;
  }
  return out;
}

export function t(key, params = {}) {
  if (typeof key !== "string") throw new Error("string key must be text");
  let v = strings;
  for (const part of key.split(".")) {
    if (v === null || typeof v !== "object" || !Object.prototype.hasOwnProperty.call(v, part)) throw new Error("unknown string key: " + key);
    v = v[part];
  }
  if (typeof v !== "string") throw new Error("not a text: " + key);
  return format(v, params);
}

export default strings;
